import base64
from cryptography.hazmat.primitives import serialization, hashes
from cryptography.hazmat.primitives.asymmetric import padding
from cryptography.hazmat.backends import default_backend

pubkey64 = """

"""
pubkeybytes = base64.b64decode(pubkey64)
public_key = serialization.load_pem_public_key(pubkeybytes, backend=default_backend())

data = "jjj"
encrypted_data = public_key.encrypt(
    data.encode("utf-8"),
    padding.OAEP(
        mgf=padding.MGF1(algorithm=hashes.SHA256()),
        algorithm=hashes.SHA256(),
        label=None
    )
)
print(f"Encrypted data:\n{encrypted_data}")

privkey64 = """

"""
privkeybytes = base64.b64decode(privkey64)
private_key = serialization.load_pem_private_key(privkeybytes, password=None, backend=default_backend())

decrypted_data = private_key.decrypt(
    encrypted_data,
    padding.OAEP(
        mgf=padding.MGF1(algorithm=hashes.SHA256()),
        algorithm=hashes.SHA256(),
        label=None
    )
)

decrypted_string = decrypted_data.decode("utf-8")
print(f"\nDecrypted string\n{decrypted_string}")
